cat > s4.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage({viewport:{width:1280,height:900}});
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForLoadState('networkidle');
await p.goto('http://127.0.0.1:54569/pricing');
await p.waitForLoadState('networkidle');
const row = p.locator('tr[data-sku="P-1043"]');
await row.hover();
await row.locator('.setd').click();
const r = await p.locator('#track').boundingBox();
await p.mouse.click(r.x + 480*17/60, r.y + r.height/2);
console.log('val:', await p.locator('#val').textContent(), 'psku:', await p.locator('#psku').textContent());
if ((await p.locator('#val').textContent()) === '17%') {
  await p.click('#apply');
  await p.waitForTimeout(800);
}
const rows = await p.$$eval('#pt tr[data-sku]', trs => trs.map(t => t.dataset.sku + ' ' + t.querySelector('.d').textContent));
console.log(rows.join('\n'));
await p.goto('http://127.0.0.1:54569/pricing');
await p.waitForLoadState('networkidle');
console.log('after reload:', await p.$$eval('#pt tr[data-sku]', trs => trs.map(t => t.dataset.sku + ' ' + t.querySelector('.d').textContent).join(', ')));
await b.close();
EOF
node s4.mjs
